/**
 * XDR-JSON (SEP-0051) rendering, decoding and rejection behaviour of the types
 * generated from Stellar-ledger-entries.x.
 */
class XdrJsonLedgerEntriesTest {

  @Test
  fun thresholdsXdrRoundTripsThroughItsJsonTree() {
    assertRoundTripThresholdsXdr(sampleThresholdsXdr(7, 0))
    assertRoundTripThresholdsXdr(sampleThresholdsXdr(7, SAMPLE_DEPTH))
  }

  private fun assertRoundTripThresholdsXdr(value: ThresholdsXdr) {
    val tree = value.toXdrJsonElement()
    val text = ThresholdsXdr.fromXdrJsonElement(tree).toXdrJson()
    assertEquals(tree, ThresholdsXdr.fromXdrJson(text).toXdrJsonElement())
    assertEquals(text, ThresholdsXdr.fromXdrJson(text).toXdrJson())
  }

  @Test
  fun thresholdsXdrRejectsInputOfTheWrongShape() {
    assertFailsWith<IllegalArgumentException> { ThresholdsXdr.fromXdrJsonElement(JsonNull) }
  }


