  @Test
  fun bucketMetadataExtXdrRoundTripsThroughItsJsonTree() {
    assertRoundTripBucketMetadataExtXdr(sampleBucketMetadataExtXdr(8188, 0))
    assertRoundTripBucketMetadataExtXdr(sampleBucketMetadataExtXdr(8188, SAMPLE_DEPTH))
  }

  private fun assertRoundTripBucketMetadataExtXdr(value: BucketMetadataExtXdr) {
    val tree = value.toXdrJsonElement()
    val text = BucketMetadataExtXdr.fromXdrJsonElement(tree).toXdrJson()
    assertEquals(tree, BucketMetadataExtXdr.fromXdrJson(text).toXdrJsonElement())
    assertEquals(text, BucketMetadataExtXdr.fromXdrJson(text).toXdrJson())
  }

  @Test
  fun bucketMetadataExtXdrRendersVoidArmAsV0() {
    val value = sampleBucketMetadataExtXdrVoidArm(8188, 0)
