    val decoded = BucketMetadataExtXdr.fromXdrJsonElement(tree)
    assertEquals(value.discriminant, decoded.discriminant)
    assertEquals(tree, decoded.toXdrJsonElement())
  }

  @Test
  fun bucketMetadataExtXdrRendersBucketListTypeArmAsV1() {
    val value = sampleBucketMetadataExtXdrBucketListTypeArm(8193, 0)
    val tree = value.toXdrJsonElement()
    assertEquals(listOf("v1"), jsonKeys(tree))
    val decoded = BucketMetadataExtXdr.fromXdrJsonElement(tree)
    assertEquals(value.discriminant, decoded.discriminant)
    assertEquals(tree, decoded.toXdrJsonElement())
  }

  @Test
  fun bucketMetadataExtXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      BucketMetadataExtXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      BucketMetadataExtXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> {
      BucketMetadataExtXdr.fromXdrJsonElement(JsonPrimitive("not_a_name_this_type_declares"))
    }
    assertFailsWith<IllegalArgumentException> { BucketMetadataExtXdr.fromXdrJsonElement(JsonNull) }
  }


